/* --- SOURCE: js/seed.js --- */



const Seed = {
    run: () => {
        console.log('🌱 Running seed script...');

        const vehiclesToSeed = [
            // BIKES
            { regNo: 'Sampath', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9170997653', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },
            { regNo: 'Prathap', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9176093889', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },
            { regNo: 'Naween', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9175376733', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },
            { regNo: 'Upali', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9175380028', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },
            { regNo: 'Thimal', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9176093835', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },
            { regNo: 'Dinesh', brand: 'Bike', model: 'Bike', type: 'Bike', trackingId: '9176044130', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Petrol', year: 2023 },

            // LORRIES
            { regNo: 'LL-9815', brand: 'Leyland', model: 'Truck', type: 'Lorry', trackingId: '9175379873', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Diesel', year: 2023 },
            { regNo: 'LL-0906', brand: 'Leyland', model: 'Truck', type: 'Lorry', trackingId: '9175379916', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Diesel', year: 2023 },
            { regNo: 'LL-6343', brand: 'Leyland', model: 'Truck', type: 'Lorry', trackingId: '9175376434', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Diesel', year: 2023 },

            // VANS
            { regNo: 'Shihardeen', brand: 'Van', model: 'Van', type: 'Van', trackingId: '9175376462', trackingPassword: 'Track@2023', status: 'Active', fuelType: 'Diesel', year: 2023 }
        ];

        const existing = Store.Vehicles.getAll();
        console.log('📦 Existing vehicles:', existing.length);

        let added = 0;
        vehiclesToSeed.forEach(seed => {
            const exists = existing.find(v => v.regNo === seed.regNo || v.trackingId === seed.trackingId);
            if (!exists) {
                const newVehicle = {
                    id: Utils.generateId(),
                    ...seed
                };
                console.log('➕ Seeding vehicle:', seed.regNo, 'with ID:', seed.trackingId);
                Store.Vehicles.add(newVehicle);
                added++;
            } else {
                console.log('✓ Vehicle already exists:', seed.regNo);
            }
        });

        console.log(`✅ Seed complete. Added ${added} vehicles.`);
        console.log('📊 Total vehicles now:', Store.Vehicles.getAll().length);
    }
};


/* --- SOURCE: js/modules/vehicles.js --- */
/* js/modules/vehicles.js */



const VehicleModule = {
    init: (container) => {
        VehicleModule.container = container;
        VehicleModule.renderList();
    },

    renderList: () => {
        const vehicles = Store.Vehicles.getAll();

        let rows = vehicles.map(v => `
            <tr>
                <td>
                    <div style="font-weight: 500;">${v.regNo}</div>
                    <div style="font-size: 0.8rem; color: var(--text-muted);">${v.brand} ${v.model}</div>
                </td>
                <td>${v.type}</td>
                <td>${v.fuelType}</td>
                <td><span class="badge ${v.status === 'Active' ? 'badge-success' : 'badge-danger'}">${v.status}</span></td>
                <td>
                    <div class="flex gap-2">
                        <button class="btn-icon btn-outline edit-btn" data-id="${v.id}" title="Edit">
                            <i data-lucide="edit-2" style="width: 16px; height: 16px;"></i>
                        </button>
                        <button class="btn-icon btn-outline text-danger delete-btn" data-id="${v.id}" title="Delete">
                            <i data-lucide="trash-2" style="width: 16px; height: 16px;"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `).join('');

        if (vehicles.length === 0) {
            rows = `<tr><td colspan="5" style="text-align:center; padding: 2rem;">No vehicles found. Add one to get started.</td></tr>`;
        }

        VehicleModule.container.innerHTML = `
            <div class="card">
                <div class="card-header">
                    <div class="flex gap-4">
                        <input type="text" id="searchInput" class="form-input" placeholder="Search vehicles..." style="max-width: 300px;">
                        <select id="statusFilter" class="form-select" style="max-width: 150px;">
                            <option value="all">All Status</option>
                            <option value="Active">Active</option>
                            <option value="Inactive">Inactive</option>
                        </select>
                    </div>
                    <button class="btn btn-primary" id="addVehicleBtn">
                        <i data-lucide="plus"></i> Add Vehicle
                    </button>
                </div>
                <div class="table-container">
                    <table class="table">
                        <thead>
                            <tr>
                                <th>Vehicle Details</th>
                                <th>Type</th>
                                <th>Fuel</th>
                                <th>Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rows}
                        </tbody>
                    </table>
                </div>
            </div>
            
            <!-- Add/Edit Modal -->
            <div class="modal-overlay" id="vehicleModal">
                <div class="modal">
                    <div class="modal-header">
                        <h3 class="card-title" id="modalTitle">Add Vehicle</h3>
                        <button class="icon-btn close-modal"><i data-lucide="x"></i></button>
                    </div>
                    <form id="vehicleForm">
                        <div class="modal-body">
                            <input type="hidden" name="id">
                            <div class="form-group">
                                <label class="form-label">Registration No</label>
                                <input type="text" name="regNo" class="form-input" required placeholder="e.g. CAB-1234">
                            </div>
                            <div class="flex gap-4">
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Brand</label>
                                    <input type="text" name="brand" class="form-input" required placeholder="Toyota">
                                </div>
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Model</label>
                                    <input type="text" name="model" class="form-input" required placeholder="Prius">
                                </div>
                            </div>
                            <div class="flex gap-4">
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Type</label>
                                    <select name="type" class="form-select">
                                        <option value="Car">Car</option>
                                        <option value="Van">Van</option>
                                        <option value="Lorry">Lorry</option>
                                        <option value="Bike">Bike</option>
                                        <option value="Bus">Bus</option>
                                    </select>
                                </div>
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Year</label>
                                    <input type="number" name="year" class="form-input" placeholder="2020">
                                </div>
                            </div>
                             <div class="flex gap-4">
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Fuel Type</label>
                                    <select name="fuelType" class="form-select">
                                        <option value="Petrol">Petrol</option>
                                        <option value="Diesel">Diesel</option>
                                        <option value="Electric">Electric</option>
                                        <option value="Hybrid">Hybrid</option>
                                    </select>
                                </div>
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Status</label>
                                    <select name="status" class="form-select">
                                        <option value="Active">Active</option>
                                        <option value="Inactive">Inactive</option>
                                        <option value="Repair">Under Repair</option>
                                    </select>
                                </div>
                            </div>
                             <div class="flex gap-4">
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Tracking ID</label>
                                    <input type="text" name="trackingId" class="form-input" placeholder="Device ID">
                                </div>
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Tracking Password</label>
                                    <input type="text" name="trackingPassword" class="form-input" placeholder="Password">
                                </div>
                            </div>
                        </div>
                        <div class="modal-footer">
                            <button type="button" class="btn btn-outline close-modal">Cancel</button>
                            <button type="submit" class="btn btn-primary">Save Vehicle</button>
                        </div>
                    </form>
                </div>
            </div>
        `;

        // Re-render icons
        lucide.createIcons();

        // Attach Listeners
        VehicleModule.attachListeners();
    },

    attachListeners: () => {
        const modal = document.getElementById('vehicleModal');
        const form = document.getElementById('vehicleForm');

        // Open Modal
        document.getElementById('addVehicleBtn').addEventListener('click', () => {
            document.getElementById('modalTitle').textContent = 'Add Vehicle';
            form.reset();
            form.elements['id'].value = '';
            modal.classList.add('active');
        });

        // Close Modal
        document.querySelectorAll('.close-modal').forEach(btn => {
            btn.addEventListener('click', () => {
                modal.classList.remove('active');
            });
        });

        // Form Submit
        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const formData = new FormData(form);
            const data = Object.fromEntries(formData.entries());

            if (data.id) {
                // Edit
                Store.Vehicles.update(data);
            } else {
                // Add
                data.id = Utils.generateId();
                Store.Vehicles.add(data);
            }

            modal.classList.remove('active');
            VehicleModule.renderList(); // Refresh
        });

        // Edit Buttons
        document.querySelectorAll('.edit-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const id = btn.dataset.id;
                const vehicle = Store.Vehicles.getAll().find(v => v.id === id);
                if (vehicle) {
                    document.getElementById('modalTitle').textContent = 'Edit Vehicle';
                    // Populate Form
                    for (const key in vehicle) {
                        if (form.elements[key]) {
                            form.elements[key].value = vehicle[key];
                        }
                    }
                    modal.classList.add('active');
                }
            });
        });

        // Delete Buttons
        document.querySelectorAll('.delete-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                if (confirm('Are you sure you want to delete this vehicle?')) {
                    Store.Vehicles.delete(btn.dataset.id);
                    VehicleModule.renderList();
                }
            });
        });

        // Search Filter
        document.getElementById('searchInput').addEventListener('input', (e) => {
            const term = e.target.value.toLowerCase();
            // Simple client-side search... 
            // Ideally we'd separate data fetching and rendering, but for now:
            const rows = document.querySelectorAll('tbody tr');
            rows.forEach(row => {
                const text = row.innerText.toLowerCase();
                row.style.display = text.includes(term) ? '' : 'none';
            });
        });
    }
};


