const ExpenseModule = {
    init: (container) => {
        ExpenseModule.container = container;
        ExpenseModule.renderList();
    },

    renderList: () => {
        const expenses = Store.Expenses.getAll().sort((a, b) => new Date(b.date) - new Date(a.date));
        const vehicles = Store.Vehicles.getAll();
        const getVehicle = (id) => vehicles.find(v => v.id === id) || { regNo: 'General/Other' };

        let totalExpenses = 0;
        let rows = expenses.map(e => {
            totalExpenses += parseFloat(e.amount);
            return `
            <tr>
                <td>
                    <div style="font-weight: 500;">${e.date}</div>
                    <div style="font-size: 0.8rem; color: var(--text-muted);">${e.category}</div>
                </td>
                <td>
                    <div style="font-weight: 500;">${e.title}</div>
                    ${e.vehicleId ? `<div style="font-size:0.8rem; color:var(--text-muted)">${getVehicle(e.vehicleId).regNo}</div>` : ''}
                </td>
                <td>${Utils.formatCurrency(e.amount)}</td>
                <td>
                    <span class="badge badge-warning">${e.status || 'Paid'}</span>
                </td>
                <td>
                    <div class="flex gap-2">
                        <button class="btn-icon btn-outline edit-btn" data-id="${e.id}" title="Edit">
                            <i data-lucide="edit-2" style="width: 16px; height: 16px;"></i>
                        </button>
                        <button class="btn-icon btn-outline text-danger delete-btn" data-id="${e.id}" title="Delete">
                            <i data-lucide="trash-2" style="width: 16px; height: 16px;"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
        }).join('');

        if (expenses.length === 0) {
            rows = `<tr><td colspan="5" style="text-align:center; padding: 2rem;">No expense records found.</td></tr>`;
        }

        ExpenseModule.container.innerHTML = `
            <div class="card">
                <div class="card-header">
                     <div class="flex flex-col">
                        <span class="card-title">Expense History</span>
                         <span class="text-muted" style="font-size:0.9rem">Total: <span class="text-danger">${Utils.formatCurrency(totalExpenses)}</span></span>
                    </div>
                    <button class="btn btn-primary" id="addExpenseBtn">
                        <i data-lucide="plus"></i> Add Expense
                    </button>
                </div>
                <div class="table-container">
                    <table class="table">
                        <thead>
                            <tr>
                                <th>Date & Category</th>
                                <th>Description / Vehicle</th>
                                <th>Amount</th>
                                <th>Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rows}
                        </tbody>
                    </table>
                </div>
            </div>
            
            <!-- Add/Edit Expense Modal -->
            <div class="modal-overlay" id="expenseModal">
                <div class="modal">
                    <div class="modal-header">
                        <h3 class="card-title" id="expenseModalTitle">Add Expense</h3>
                        <button class="icon-btn close-modal"><i data-lucide="x"></i></button>
                    </div>
                    <form id="expenseForm">
                        <div class="modal-body">
                            <input type="hidden" name="id">
                            <div class="flex gap-4">
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Date</label>
                                    <input type="date" name="date" class="form-input" required value="${Utils.getTodayDateInput()}">
                                </div>
                                <div class="form-group" style="flex:1">
                                    <label class="form-label">Amount</label>
                                    <input type="number" name="amount" class="form-input" step="0.01" required placeholder="0.00">
                                </div>
                            </div>
                            <div class="form-group">
                                <label class="form-label">Category</label>
                                <select name="category" class="form-select">
                                    <option value="Maintenance">Maintenance / Service</option>
                                    <option value="Repair">Repair</option>
                                    <option value="Insurance">Insurance</option>
                                    <option value="License">License Fee</option>
                                    <option value="Fine">Fines</option>
                                    <option value="Other">Other</option>
                                </select>
                            </div>
                            <div class="form-group">
                                <label class="form-label">Description (Title)</label>
                                <input type="text" name="title" class="form-input" required placeholder="e.g. Annual Service">
                            </div>
                            <div class="form-group">
                                <label class="form-label">Vehicle (Optional)</label>
                                <select name="vehicleId" class="form-select">
                                    <option value="">General Expense (No specific vehicle)</option>
                                    ${vehicles.filter(v => v.status === 'Active').map(v => `<option value="${v.id}">${v.regNo} (${v.brand})</option>`).join('')}
                                </select>
                            </div>
                        </div>
                        <div class="modal-footer">
                            <button type="button" class="btn btn-outline close-modal">Cancel</button>
                            <button type="submit" class="btn btn-primary">Save Expense</button>
                        </div>
                    </form>
                </div>
            </div>
        `;

        lucide.createIcons();
        ExpenseModule.attachListeners();
    },

    attachListeners: () => {
        const modal = document.getElementById('expenseModal');
        const form = document.getElementById('expenseForm');

        document.getElementById('addExpenseBtn').addEventListener('click', () => {
            document.getElementById('expenseModalTitle').textContent = 'Add Expense';
            form.reset();
            form.elements['id'].value = '';
            modal.classList.add('active');
        });

        document.querySelectorAll('.close-modal').forEach(btn => {
            btn.addEventListener('click', () => {
                modal.classList.remove('active');
            });
        });

        form.addEventListener('submit', (e) => {
            e.preventDefault();
            const formData = new FormData(form);
            const data = Object.fromEntries(formData.entries());

            data.amount = parseFloat(data.amount);

            if (data.id) {
                Store.Expenses.update(data);
            } else {
                data.id = Utils.generateId();
                Store.Expenses.add(data);
            }

            modal.classList.remove('active');
            ExpenseModule.renderList();
        });

        // Edit
        document.querySelectorAll('.edit-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const id = btn.dataset.id;
                const entry = Store.Expenses.getAll().find(e => e.id === id);
                if (entry) {
                    document.getElementById('expenseModalTitle').textContent = 'Edit Expense';
                    for (const key in entry) {
                        if (form.elements[key]) {
                            form.elements[key].value = entry[key];
                        }
                    }
                    modal.classList.add('active');
                }
            });
        });

        // Delete
        document.querySelectorAll('.delete-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                if (confirm('Delete this expense record?')) {
                    Store.Expenses.delete(btn.dataset.id);
                    ExpenseModule.renderList();
                }
            });
        });
    }
};


/* --- SOURCE: js/modules/reports.js --- */
