/* js/modules/settings.js */



const SettingsModule = {
    init: (container) => {
        SettingsModule.container = container;
        SettingsModule.render();
    },

    render: () => {
        SettingsModule.container.innerHTML = `
            <div class="flex flex-col gap-4">
                <h2 style="font-size:1.5rem; margin-bottom:1rem;">System Settings</h2>
                
                <!-- Data Management Card -->
                <div class="card">
                    <div class="card-header">
                        <span class="card-title">Data Management (Backup & Restore)</span>
                        <i data-lucide="database" class="text-muted"></i>
                    </div>
                    <div class="card-body">
                        <div class="alert alert-info" style="margin-bottom: 1.5rem; background: #eff6ff; color: #1e3a8a; padding: 1rem; border-radius: 0.5rem; border: 1px solid #bfdbfe;">
                            <div style="font-weight: 600; margin-bottom: 0.5rem;">Important Note:</div>
                            <p style="font-size: 0.9rem;">
                                Use this section to migrate your data to another computer or to keep a backup. 
                                The <strong>Backup</strong> button downloads a CSV file containing ALL your system data.
                                The <strong>Restore</strong> feature will REPLACE your current data with the data from the file.
                            </p>
                        </div>

                        <div class="flex flex-col gap-6">
                            <!-- Backup Section -->
                            <div style="border-bottom: 1px solid var(--border-color); padding-bottom: 1.5rem;">
                                <h3 style="font-size: 1.1rem; font-weight: 500; margin-bottom: 1rem;">Backup Data</h3>
                                <p class="text-muted" style="margin-bottom: 1rem;">Download a full system backup file (.csv).</p>
                                <button class="btn btn-primary" id="backupBtn">
                                    <i data-lucide="download-cloud"></i> Download Full Backup
                                </button>
                            </div>

                            <!-- Restore Section -->
                            <div>
                                <h3 style="font-size: 1.1rem; font-weight: 500; margin-bottom: 1rem;">Restore Data</h3>
                                <p class="text-muted" style="margin-bottom: 1rem;">Select a previously downloaded backup file to restore.</p>
                                <div class="flex gap-4 items-center">
                                    <input type="file" id="restoreInput" accept=".csv" class="form-input" style="max-width: 300px;">
                                    <button class="btn btn-danger" id="restoreBtn">
                                        <i data-lucide="upload-cloud"></i> Restore Data
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- App Info Card -->
                <div class="card">
                    <div class="card-header">
                        <span class="card-title">Application Info</span>
                        <i data-lucide="info" class="text-muted"></i>
                    </div>
                    <div class="card-body">
                        <div class="flex justify-between" style="border-bottom: 1px solid var(--border-color); padding: 0.8rem 0;">
                            <span class="text-muted">App Name</span>
                            <span style="font-weight: 500;">VMS Pro</span>
                        </div>
                         <div class="flex justify-between" style="border-bottom: 1px solid var(--border-color); padding: 0.8rem 0;">
                            <span class="text-muted">Version</span>
                            <span style="font-weight: 500;">1.0.0</span>
                        </div>
                        <div class="flex justify-between" style="padding-top: 0.8rem;">
                            <span class="text-muted">Platform</span>
                            <span style="font-weight: 500;">Web / LocalStorage</span>
                        </div>
                    </div>
                </div>
            </div>
        `;

        if (window.lucide) lucide.createIcons();
        SettingsModule.attachListeners();
    },

    attachListeners: () => {
        // Backup Logic
        document.getElementById('backupBtn').addEventListener('click', () => {
            SettingsModule.performBackup();
        });

        // Restore Logic
        document.getElementById('restoreBtn').addEventListener('click', () => {
            const input = document.getElementById('restoreInput');
            if (input.files && input.files[0]) {
                if (confirm('WARNING: This will replace ALL current data with the backup. This action cannot be undone. Are you sure?')) {
                    SettingsModule.performRestore(input.files[0]);
                }
            } else {
                alert('Please select a file first.');
            }
        });
    },

    performBackup: () => {
        try {
            // 1. Gather all vms_* keys
            const keys = Object.keys(localStorage).filter(k => k.startsWith('vms_'));
            const data = [];

            // Header
            data.push('Key,Value');

            keys.forEach(key => {
                const val = localStorage.getItem(key);
                // Escape double quotes by doubling them: " -> ""
                const escapedVal = val.replace(/"/g, '""');
                // Wrap in quotes
                data.push(`"${key}","${escapedVal}"`);
            });

            const csvContent = data.join('\n');
            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.setAttribute('download', `VMS_FULL_BACKUP_${new Date().toISOString().slice(0, 10)}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

        } catch (error) {
            console.error('Backup failed:', error);
            alert('Backup failed: ' + error.message);
        }
    },

    performRestore: (file) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const content = e.target.result;
                const lines = content.split('\n');

                // Simple CSV Parser for formatted Key,Value
                // Note: This relies on the specific format generated by performBackup

                let restoreCount = 0;

                // Skip header (index 0)
                for (let i = 1; i < lines.length; i++) {
                    const line = lines[i].trim();
                    if (!line) continue;

                    // Regex to match: "KEY","VALUE"
                    // Capture group 1: Key
                    // Capture group 2: Value
                    const match = line.match(/^"([^"]+)","(.*)"$/);

                    if (match && match.length === 3) {
                        const key = match[1];
                        let value = match[2];

                        // Unescape: "" -> "
                        value = value.replace(/""/g, '"');

                        // Validate JSON if possible, or just trust the string
                        try {
                            JSON.parse(value); // Check validity
                            localStorage.setItem(key, value);
                            restoreCount++;
                        } catch (parseError) {
                            console.warn(`Skipping invalid JSON for key ${key}`);
                        }
                    }
                }

                alert(`Restore successful! restored for ${restoreCount} items. The page will now reload.`);
                window.location.reload();

            } catch (error) {
                console.error('Restore failed:', error);
                alert('Restore failed: ' + error.message);
            }
        };
        reader.readAsText(file);
    }
};


/* --- SOURCE: js/app.js --- */
/* App.js - Main Application Controller */













// Initialize Lucide Icons
const updateIcons = () => {
    if (window.lucide) {
        lucide.createIcons();
    } else {
        console.warn('Lucide icons not loaded yet.');
    }
};

const App = {
    init: () => {
        console.log('VMS System Initializing...');
        Store.init();

        // Seed Data
        import('./seed.js').then(module => {
            module.Seed.run();
        });

        // Setup Router
        window.addEventListener('hashchange', App.handleRoute);

        // Handle initial load - check if document is already ready
        if (document.readyState === 'complete' || document.readyState === 'interactive') {
            setTimeout(App.handleRoute, 1); // Defer slightly to ensure DOM is fully parsed if interactive
        } else {
            window.addEventListener('DOMContentLoaded', App.handleRoute);
        }

        // Setup Global Event Listeners
        App.setupEventListeners();

        // Initial Theme Check
        if (localStorage.getItem('vms_theme') === 'light') {
            document.body.classList.add('light-mode');
            const icon = document.querySelector('.theme-toggle i');
            if (icon) icon.setAttribute('data-lucide', 'moon');
        }

        updateIcons();
    },

    setupEventListeners: () => {
        // Theme Toggle
        document.querySelector('.theme-toggle').addEventListener('click', () => {
            document.body.classList.toggle('light-mode');
            const isLight = document.body.classList.contains('light-mode');
            localStorage.setItem('vms_theme', isLight ? 'light' : 'dark');

            // Toggle Icon
            const icon = document.querySelector('.theme-toggle i');
            icon.setAttribute('data-lucide', isLight ? 'moon' : 'sun');
            updateIcons();
        });

        // Sidebar Navigation Active State
        const navItems = document.querySelectorAll('.nav-item[data-page]');
        navItems.forEach(item => {
            item.addEventListener('click', () => {
                navItems.forEach(n => n.classList.remove('active'));
                item.classList.add('active');
            });
        });
    },

    handleRoute: () => {
        const hash = window.location.hash.slice(1) || 'dashboard'; // Default to dashboard
        const contentArea = document.getElementById('contentArea');
        const pageTitle = document.getElementById('pageTitle');

        // Update Sidebar Active State based on Hash
        document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
        const activeLink = document.querySelector(`.nav-item[href="#${hash}"]`);
        if (activeLink) activeLink.classList.add('active');

        // Render Content
        switch (hash) {
            case 'dashboard':
                pageTitle.textContent = 'Dashboard';
                App.renderDashboard(contentArea);
                break;
            case 'vehicles':
                pageTitle.textContent = 'Vehicle Management';
                VehicleModule.init(contentArea);
                break;
            case 'drivers':
                pageTitle.textContent = 'Driver Management';
                DriverModule.init(contentArea);
                break;
            case 'trips':
                pageTitle.textContent = 'Trip Management';
                TripModule.init(contentArea);
                break;
            case 'fuel':
                pageTitle.textContent = 'Fuel Management';
                FuelModule.init(contentArea);
                break;
            case 'expenses':
                pageTitle.textContent = 'Expenses';
                ExpenseModule.init(contentArea);
                break;
            case 'reports':
                pageTitle.textContent = 'Reports';
                ReportsModule.init(contentArea);
                break;
            case 'maintenance':
                pageTitle.textContent = 'Service & Maintenance';
                MaintenanceModule.init(contentArea);
                break;
            case 'tracking':
                pageTitle.textContent = 'Vehicle Tracking';
                TrackingModule.init(contentArea);
                break;
            case 'settings':
                pageTitle.textContent = 'Settings';
                SettingsModule.init(contentArea);
                break;
            default:
                pageTitle.textContent = 'Page Not Found';
                contentArea.innerHTML = '<h2>404</h2><p>The requested page does not exist.</p>';
        }

        updateIcons();
    },

    // --- Page Renderers ---

    renderDashboard: (container) => {
        // Calculate Stats
        const vehicles = Store.Vehicles.getAll();
        const drivers = Store.Drivers.getAll();

        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();

        // Calculate Monthly Costs
        let monthlyCost = 0;

        // Fuel Costs
        const fuelEntries = Store.Fuel.getAll();
        fuelEntries.forEach(f => {
            const d = new Date(f.date);
            if (d.getMonth() === currentMonth && d.getFullYear() === currentYear) {
                monthlyCost += parseFloat(f.cost);
            }
        });

        // Expense Costs
        const expenses = Store.Expenses.getAll();
        expenses.forEach(e => {
            const d = new Date(e.date);
            if (d.getMonth() === currentMonth && d.getFullYear() === currentYear) {
                monthlyCost += parseFloat(e.amount);
            }
        });

        const stats = {
            totalVehicles: vehicles.length,
            activeVehicles: vehicles.filter(v => v.status === 'Active').length,
            totalDrivers: drivers.length,
            monthlyCost: monthlyCost
        };

        // Recent Activity (Merge Trips, Fuel, Expenses)
        let activity = [];
        Store.Trips.getAll().forEach(t => activity.push({ type: 'Trip', date: t.startDate, title: `Trip: ${t.purpose || 'Unknown'}`, details: `${t.status}` }));
        Store.Fuel.getAll().forEach(f => activity.push({ type: 'Fuel', date: f.date, title: `Fuel: ${Utils.formatCurrency(f.cost)}`, details: `${f.liters} L` }));
        Store.Expenses.getAll().forEach(e => activity.push({ type: 'Expense', date: e.date, title: `${e.category}: ${e.title}`, details: Utils.formatCurrency(e.amount) }));

        // Sort by date desc and take top 5
        activity.sort((a, b) => new Date(b.date) - new Date(a.date));
        activity = activity.slice(0, 5);

        const activityHtml = activity.length ? activity.map(a => `
            <div style="display:flex; justify-content:space-between; padding: 0.8rem 0; border-bottom: 1px solid var(--border-color);">
                <div>
                    <div style="font-weight:500;">${a.title}</div>
                    <div style="font-size:0.8rem; color:var(--text-muted);">${a.type} • ${a.date}</div>
                </div>
                <div style="font-size:0.9rem;">${a.details}</div>
            </div>
        `).join('') : '<p class="text-muted">No recent activity.</p>';

        container.innerHTML = `
            <div class="stats-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 1.5rem; margin-bottom: 2rem;">
                <div class="card">
                    <div class="card-header">
                        <span class="card-title">Total Vehicles</span>
                        <i data-lucide="car" class="text-muted"></i>
                    </div>
                    <div style="font-size: 2.5rem; font-weight: 700;">${stats.totalVehicles}</div>
                    <div class="text-success" style="font-size: 0.9rem; margin-top: 0.5rem;">
                        ${stats.activeVehicles} Active
                    </div>
                </div>
                
                <div class="card">
                    <div class="card-header">
                        <span class="card-title">Total Drivers</span>
                        <i data-lucide="users" class="text-muted"></i>
                    </div>
                    <div style="font-size: 2.5rem; font-weight: 700;">${stats.totalDrivers}</div>
                </div>

                <div class="card">
                    <div class="card-header">
                        <span class="card-title">Monthly Cost</span>
                        <i data-lucide="dollar-sign" class="text-muted"></i>
                    </div>
                    <div style="font-size: 2.5rem; font-weight: 700;">${Utils.formatCurrency(stats.monthlyCost)}</div>
                    <div class="text-muted" style="font-size: 0.9rem; margin-top: 0.5rem;">
                        ${new Date().toLocaleString('default', { month: 'long' })}
                    </div>
                </div>
            </div>
            
            <div class="card">
                <div class="card-header">
                    <h3 class="card-title">Recent Activity</h3>
                </div>
                <div class="card-body">
                    ${activityHtml}
                </div>
            </div>
        `;
    }
};

// Initialize App
App.init();

